const addFlag = (mask, bit) => mask | (1 << bit);
const removeFlag = (mask, bit) => mask & ~(1 << bit);

function countBits32(value) {
  value >>>= 0;
  let count = 0;
  while (value) {
    value &= value - 1; // Remove the lowest set bit.
    count++;
  }
  return count;
}

let permissions = addFlag(0, 2);
