function lineTotal(line: Line): number {
  if (!Number.isSafeInteger(line.quantity) || line.quantity < 0 || !Number.isFinite(line.unitPrice) || line.unitPrice < 0) {
    throw new RangeError("nonnegative integer quantity and finite price required");
  }
  return line.unitPrice * line.quantity;
}

function discountFor(subtotal: number, isMember: boolean): number {
  if (!isMember) return 0;
  return subtotal >= 100 ? subtotal * 0.1 : 0;
}

export function orderTotal(lines: readonly Line[], isMember: boolean): number {
  const subtotal = lines.reduce((sum, line) => sum + lineTotal(line), 0);
  if (!Number.isFinite(subtotal)) throw new RangeError("subtotal overflow");
  return subtotal - discountFor(subtotal, isMember);
}

