assert.equal(ifMatch("*", null), false);
assert.equal(ifMatch("*", '"b"'), true);
assert.equal(ifMatch(', "b",', '"b"'), true); // Empty list elements ignored.
assert.throws(() => ifMatch('"a" "b"', '"b"'));
